/** Maybe monad for safe null/undefined handling with method chaining. */
import { isNil } from "./detection.js";
/** Wraps a value in a Maybe for safe null/undefined handling. */
export const maybe = (val) => {
    const isNilMethod = () => isNil(val);
    const value = () => val;
    const map = (fn) => {
        return maybe(isNil(val) ? null : fn(val));
    };
    const filter = (fn) => {
        return maybe(isNil(val) || !fn(val) ? null : val);
    };
    const orElse = (fn) => {
        return maybe(isNil(val) ? fn() : val);
    };
    const tap = (fn) => {
        if (!isNil(val)) {
            fn(val);
        }
        return maybeInstance;
    };
    const toArray = () => {
        return isNil(val) ? [] : [val];
    };
    const inspect = () => {
        return `Maybe(${isNil(val) ? "null" : val})`;
    };
    const maybeInstance = {
        isNil: isNilMethod,
        value,
        map,
        filter,
        when: filter,
        orElse,
        getOrElse: orElse,
        tap,
        toArray,
        inspect,
    };
    return maybeInstance;
};
